const fs = require\('fs'\);
const { PNG } = require\('pngjs'\);

const files = ['burger-classic.png','burger-jalapeno.png','burger-poulet.png','burger-bacon.png'];

for \(const f of files\) {
  const png = PNG.sync.read\(fs.readFileSync\(f\)\);
  const { width, height, data } = png;
  // Echantillonner 20 pixels visibles \(non transparents\) au centre
  const samples = [];
  for \(let y = Math.floor\(height*0.3\); y < Math.floor\(height*0.7\) && samples.length < 10; y+=5\) {
    for \(let x = Math.floor\(width*0.3\); x < Math.floor\(width*0.7\) && samples.length < 10; x+=5\) {
      const i = \(y*width+x\)*4;
      if \(data[i+3] > 10\) samples.push\([data[i],data[i+1],data[i+2]]\);
    }
  }
  console.log\(f, width+'x'+height, 'samples:', samples.slice\(0,5\).map\(c=>'rgb\('+c+'\)'\).join\(' '\)\);
}
")

