const fs = require\('fs'\);
const { PNG } = require\('pngjs'\);

// Scan for unique visible colors, ignoring very dark and burger-colored ones
const png = PNG.sync.read\(fs.readFileSync\('burger-jalapeno.png'\)\);
const { width, height, data } = png;
const colorBuckets = {};
for \(let y = 0; y < height; y++\) {
  for \(let x = 0; x < width; x++\) {
    const i = \(y*width+x\)*4;
    if \(data[i+3] < 100\) continue;
    // bucket by 20
    const r = Math.round\(data[i]/20\)*20;
    const g = Math.round\(data[i+1]/20\)*20;
    const b = Math.round\(data[i+2]/20\)*20;
    const key = r+','+g+','+b;
    colorBuckets[key] = \(colorBuckets[key]||0\)+1;
  }
}
const sorted = Object.entries\(colorBuckets\).sort\(\(a,b\)=>b[1]-a[1]\).slice\(0,15\);
console.log\('burger-jalapeno top colors:'\);
sorted.forEach\(\([k,v]\)=>console.log\('  rgb\('+k+'\) x'+v\)\);
")
